def banco_tipos():
    COMP, APO, NING = t("Compelling", "Convincente"), t("Supporting", "De apoyo"), t("Neither: personal taste", "Ninguna: gusto personal")
    pist = {0: t("Could informed people defend different answers with evidence? Then it is compelling.", "¿Podrían personas informadas defender respuestas distintas con evidencia? Entonces es convincente."),
            1: t("Could one source settle it, so that everyone accepts the answer? Then it is supporting.", "¿Una sola fuente la resolvería y todos aceptarían la respuesta? Entonces es de apoyo."),
            2: t("Does the answer depend only on what someone likes, so that no evidence could decide it?", "¿La respuesta depende solo de lo que a alguien le gusta, sin que ninguna evidencia pueda decidirla?")}
    datos = [
        (t("In what year did Illinois become a state?", "¿En qué año se convirtió Illinois en estado?"), 1, t("1818: one source settles it.", "1818: una fuente lo resuelve.")),
        (t("Should the minimum wage be the same in every state?", "¿Debería ser igual el salario mínimo en todos los estados?"), 0, t("Economists and voters defend different answers with data about prices, jobs, and wages.", "Economistas y votantes defienden respuestas distintas con datos sobre precios, empleo y salarios.")),
        (t("How many votes does a state get in the Electoral College?", "¿Cuántos votos tiene un estado en el Colegio Electoral?"), 1, t("It is a rule: its number of senators plus representatives. One source answers it.", "Es una regla: su número de senadores más representantes. Una fuente lo responde.")),
        (t("What is the prettiest national park?", "¿Cuál es el parque nacional más bonito?"), 2, t("“Prettiest” is taste. No evidence can decide it.", "«Más bonito» es gusto. Ninguna evidencia puede decidirlo.")),
        (t("Did the New Deal end the Great Depression?", "¿Acabó el New Deal con la Gran Depresión?"), 0, t("Historians still disagree, and each side brings evidence (unemployment, production, the war years).", "Los historiadores siguen discrepando, y cada lado aporta evidencia (desempleo, producción, los años de la guerra).")),
        (t("Who was president during the Civil War?", "¿Quién era presidente durante la Guerra Civil?"), 1, t("Abraham Lincoln: a fact.", "Abraham Lincoln: un dato.")),
        (t("Is a city better off when it builds a new stadium with public money?", "¿Le conviene a una ciudad construir un estadio nuevo con dinero público?"), 0, t("Studies, budgets, and neighborhoods give different answers; it can be argued with evidence.", "Los estudios, los presupuestos y los barrios dan respuestas distintas; se puede discutir con evidencia.")),
        (t("Which is the most fun state to visit?", "¿Cuál es el estado más divertido para visitar?"), 2, t("“Most fun” depends on each person.", "«Más divertido» depende de cada persona.")),
        (t("What percent of Chicago’s population was born in another country?", "¿Qué porcentaje de la población de Chicago nació en otro país?"), 1, t("The census gives the number.", "El censo da la cifra.")),
        (t("Was the Constitution of 1787 a democratic document?", "¿Fue la Constitución de 1787 un documento democrático?"), 0, t("It depends on what counts as democratic, and both sides can quote the document and its history.", "Depende de qué se entienda por democrático, y los dos lados pueden citar el documento y su historia.")),
        (t("When did the 19th Amendment become part of the Constitution?", "¿Cuándo entró la Decimonovena Enmienda en la Constitución?"), 1, t("1920: one source settles it.", "1920: una fuente lo resuelve.")),
        (t("Which flag has the nicest colors?", "¿Qué bandera tiene los colores más bonitos?"), 2, t("A matter of taste.", "Cuestión de gusto.")),
        (t("Should voting be required by law, as it is in some countries?", "¿Debería ser obligatorio votar por ley, como en algunos países?"), 0, t("Open, debatable with evidence from countries that do it, and of lasting importance.", "Abierta, discutible con evidencia de los países que lo hacen y de relevancia duradera.")),
        (t("How many people live in Cook County?", "¿Cuántas personas viven en el condado de Cook?"), 1, t("The census answers it with one number.", "El censo la responde con una cifra.")),
    ]
    return [{"enun": t("What kind of question is this?", "¿Qué tipo de pregunta es esta?") + "<br><strong>" + s + "</strong>",
             "ops": [COMP, APO, NING], "ok": k, "pistas": {i: pist[k] for i in range(3) if i != k}, "exp": f"<strong>{[COMP, APO, NING][k]}.</strong> " + e, "enOrden": True} for s, k, e in datos]


def banco_dimension():
    D = [t("1 · Develop questions", "1 · Desarrollar preguntas"), t("2 · Apply the tools of each discipline", "2 · Aplicar conceptos disciplinares"), t("3 · Evaluate sources and use evidence", "3 · Evaluar fuentes y usar la evidencia"), t("4 · Communicate and take action", "4 · Comunicar y actuar")]
    pist = {0: t("Is the person still deciding what to ask?", "¿La persona todavía está decidiendo qué preguntar?"),
            1: t("Is the person choosing how to look at the problem: as a historian, a geographer, an economist, or a civics expert?", "¿La persona está eligiendo cómo mirar el problema: como historiador, geógrafo, economista o experto en gobierno?"),
            2: t("Is the person judging documents or data?", "¿La persona está juzgando documentos o datos?"),
            3: t("Is the person presenting a conclusion or acting on it?", "¿La persona está presentando una conclusión o actuando a partir de ella?")}
    datos = [
        (t("A student writes: “Whom should the city’s parks serve first?” and lists three smaller questions under it.", "Un estudiante escribe: «¿A quién deben servir primero los parques de la ciudad?» y anota debajo tres preguntas menores."), 0),
        (t("A student checks whether a website about immigration says who wrote it and where its numbers come from.", "Una estudiante revisa si un sitio web sobre inmigración dice quién lo escribió y de dónde salen sus cifras."), 2),
        (t("A neighbor writes a letter to her alderman with her conclusion and three pieces of evidence.", "Una vecina escribe una carta a su concejal con su conclusión y tres pruebas."), 3),
        (t("A student decides to study a factory closing as an economist would: jobs, wages, and prices.", "Un estudiante decide estudiar el cierre de una fábrica como lo haría un economista: empleos, salarios y precios."), 1),
        (t("A student compares two newspaper stories about the same strike and notes where they disagree.", "Una estudiante compara dos noticias sobre la misma huelga y anota en qué no coinciden."), 2),
        (t("After finding an unexpected map, a student rewrites her question to make it more precise.", "Después de encontrar un mapa inesperado, una estudiante reescribe su pregunta para hacerla más precisa."), 0),
        (t("A group presents its findings at a school board meeting and proposes a new bus route.", "Un grupo presenta sus hallazgos en una reunión de la junta escolar y propone una nueva ruta de autobús."), 3),
        (t("A student decides that a question about a river border is best studied with geography: maps, distances, and resources.", "Un estudiante decide que una pregunta sobre una frontera en un río se estudia mejor con la geografía: mapas, distancias y recursos."), 1),
        (t("A student asks whether a 1917 letter was written by someone who saw the events or heard about them.", "Una estudiante se pregunta si una carta de 1917 la escribió alguien que vio los hechos o alguien que oyó hablar de ellos."), 2),
        (t("A student looks at the history of a law: who wrote it, what came before it, and what changed after it.", "Un estudiante mira la historia de una ley: quién la escribió, qué hubo antes y qué cambió después."), 1),
    ]
    return [{"enun": t("Which dimension of the inquiry arc is this?", "¿Qué dimensión del arco de indagación es esta?") + "<br><strong>" + s + "</strong>",
             "ops": D, "ok": k, "pistas": {i: pist[k] for i in range(4) if i != k}, "exp": f"<strong>{D[k]}.</strong>", "enOrden": True} for s, k in datos]


def banco_fuentes():
    datos = [
        (t("How many people in this ZIP code rent their home?", "¿Cuántas personas de este código postal viven de alquiler?"),
         [t("Census tables", "Las tablas del censo"), t("An interview with a landlord", "Una entrevista con un casero"), t("A speech by the mayor", "Un discurso del alcalde"), t("A political cartoon", "Una caricatura política")], 0, t("A count of the whole population needs the census.", "Un conteo de toda la población necesita el censo.")),
        (t("What did the city council decide about the new library, and who voted for it?", "¿Qué decidió el concejo municipal sobre la nueva biblioteca y quién votó a favor?"),
         [t("A letter to the editor", "Una carta al periódico"), t("The minutes of the council meeting", "El acta de la sesión del concejo"), t("A photo of the library", "Una foto de la biblioteca"), t("A map of the neighborhood", "Un mapa del barrio")], 1, t("The minutes are the official record of what was decided and how each member voted.", "El acta es el registro oficial de lo que se decidió y de cómo votó cada miembro.")),
        (t("How far is the nearest hospital from the new housing project?", "¿A qué distancia queda el hospital más cercano del nuevo proyecto de vivienda?"),
         [t("The city budget", "El presupuesto municipal"), t("A neighbor’s opinion", "La opinión de un vecino"), t("A map with a scale", "Un mapa con escala"), t("A newspaper editorial", "Un editorial del periódico")], 2, t("Distance is measured on a map with a scale.", "La distancia se mide en un mapa con escala.")),
        (t("How did workers describe conditions in the stockyards in 1905?", "¿Cómo describían los trabajadores las condiciones de los mataderos en 1905?"),
         [t("Today’s unemployment rate", "La tasa de desempleo actual"), t("A modern textbook summary", "El resumen de un libro de texto actual"), t("The company’s annual profits", "Las ganancias anuales de la empresa"), t("Letters, testimony, and interviews with workers from that time", "Cartas, testimonios y entrevistas de trabajadores de la época")], 3, t("Questions about how people lived something need their own voices.", "Las preguntas sobre cómo vivió la gente algo necesitan su propia voz.")),
        (t("How much money did the state spend on prisons last year?", "¿Cuánto dinero gastó el estado en prisiones el año pasado?"),
         [t("The approved state budget", "El presupuesto estatal aprobado"), t("A prison guard’s memoir", "Las memorias de un guardia de prisión"), t("A TV crime drama", "Una serie policíaca de televisión"), t("A campaign flyer", "Un folleto de campaña")], 0, t("Spending is recorded in the budget.", "El gasto queda registrado en el presupuesto.")),
        (t("What exactly does the First Amendment protect?", "¿Qué protege exactamente la Primera Enmienda?"),
         [t("A poll about free speech", "Una encuesta sobre la libertad de expresión"), t("The text of the Constitution", "El texto de la Constitución"), t("A social media post", "Una publicación en redes sociales"), t("A map of the states in 1791", "Un mapa de los estados en 1791")], 1, t("To know what a text says, read the text itself.", "Para saber qué dice un texto, se lee el propio texto.")),
        (t("How has the price of gasoline changed since 2000?", "¿Cómo ha cambiado el precio de la gasolina desde el año 2000?"),
         [t("A driver’s memory", "La memoria de un conductor"), t("An oil company ad", "Un anuncio de una petrolera"), t("A data series from a government agency", "Una serie de datos de una agencia del gobierno"), t("A photo of a gas station", "Una foto de una gasolinera")], 2, t("A change over time needs a data series.", "Un cambio a lo largo del tiempo necesita una serie de datos.")),
        (t("How did a Spanish-language newspaper report the march, compared with an English-language one?", "¿Cómo informó de la marcha un periódico en español, comparado con uno en inglés?"),
         [t("The police budget", "El presupuesto de la policía"), t("Census tables", "Las tablas del censo"), t("A map of the route", "Un mapa del recorrido"), t("The two newspapers from that date", "Los dos periódicos de esa fecha")], 3, t("To compare coverage, you read both papers.", "Para comparar la cobertura, se leen los dos periódicos.")),
    ]
    return [{"enun": t("Which source would answer this supporting question?", "¿Qué fuente respondería esta pregunta de apoyo?") + "<br><strong>" + s + "</strong>",
             "ops": ops, "ok": k, "exp": e} for s, ops, k, e in datos]


def banco_disfraz():
    datos = [
        (t("Why did the new bus route ruin the neighborhood?", "¿Por qué la nueva ruta de autobús arruinó el barrio?"),
         [t("How did the number of riders at each stop change after the new route?", "¿Cómo cambió el número de pasajeros de cada parada después de la nueva ruta?"), t("How badly did the new route ruin the neighborhood?", "¿Cuánto daño hizo la nueva ruta al barrio?"), t("Who is to blame for ruining the neighborhood?", "¿Quién tiene la culpa de arruinar el barrio?")],
         t("The other two still take the ruin for granted. The open version lets evidence go either way.", "Las otras dos siguen dando por hecha la ruina. La versión abierta deja que la evidencia vaya en cualquier dirección.")),
        (t("How did the factory owners cheat their workers in 1890?", "¿Cómo engañaban los dueños de la fábrica a sus trabajadores en 1890?"),
         [t("What wages and hours did the factory’s workers have in 1890?", "¿Qué salarios y horarios tenían los trabajadores de la fábrica en 1890?"), t("Why were the owners so greedy?", "¿Por qué eran tan codiciosos los dueños?"), t("How many ways did the owners cheat?", "¿De cuántas maneras engañaban los dueños?")],
         t("Wages and hours can be checked in records; “cheat” and “greedy” are conclusions that must be shown, not assumed.", "Los salarios y los horarios se comprueban en registros; «engañar» y «codiciosos» son conclusiones que hay que demostrar, no suponer.")),
        (t("Why is the new tax unfair to small businesses?", "¿Por qué el nuevo impuesto es injusto con los pequeños negocios?"),
         [t("What share of the new tax do small businesses pay, compared with large ones?", "¿Qué parte del nuevo impuesto pagan los pequeños negocios, comparados con los grandes?"), t("How unfair is the new tax?", "¿Qué tan injusto es el nuevo impuesto?"), t("Who wanted to hurt small businesses with this tax?", "¿Quién quería perjudicar a los pequeños negocios con este impuesto?")],
         t("Shares of a tax can be measured; “unfair” is the conclusion the inquiry must reach, not its starting point.", "La parte del impuesto que paga cada uno se puede medir; «injusto» es la conclusión a la que debe llegar la indagación, no su punto de partida.")),
        (t("How did the immigrants take jobs away from local workers?", "¿Cómo les quitaron los inmigrantes el trabajo a los trabajadores locales?"),
         [t("How did employment and wages change in the city as the immigrant population grew?", "¿Cómo cambiaron el empleo y los salarios de la ciudad a medida que crecía la población inmigrante?"), t("How many jobs did each immigrant take?", "¿Cuántos trabajos quitó cada inmigrante?"), t("Why did immigrants want to take local jobs?", "¿Por qué querían los inmigrantes quitar los trabajos locales?")],
         t("The original question assumes a cause. The open version asks what the data show and lets them say either thing.", "La pregunta original supone una causa. La versión abierta pregunta qué muestran los datos y deja que digan cualquier cosa.")),
        (t("Why did the court make the wrong decision in this case?", "¿Por qué el tribunal se equivocó en este caso?"),
         [t("What reasons did the court give for its decision, and what did the dissenting judges argue?", "¿Qué razones dio el tribunal para su decisión y qué argumentaron los jueces en desacuerdo?"), t("How wrong was the court?", "¿Qué tan equivocado estuvo el tribunal?"), t("Which judge caused the mistake?", "¿Qué juez causó el error?")],
         t("Reading both sides of the decision lets you judge it; calling it “wrong” before reading them closes the inquiry.", "Leer las dos partes de la decisión permite juzgarla; llamarla «equivocada» antes de leerlas cierra la indagación.")),
        (t("How did the new park make the neighborhood safer?", "¿Cómo hizo el nuevo parque más seguro el barrio?"),
         [t("How did the number of reported crimes near the park change in the years after it opened?", "¿Cómo cambió el número de delitos denunciados cerca del parque en los años después de su apertura?"), t("How much safer did the park make the neighborhood?", "¿Cuánto más seguro hizo el parque al barrio?"), t("Why are parks always good for safety?", "¿Por qué los parques siempre son buenos para la seguridad?")],
         t("Even a hopeful assumption is an assumption. The open question could find that crime went down, stayed the same, or went up.", "Incluso una suposición optimista es una suposición. La pregunta abierta podría encontrar que los delitos bajaron, siguieron igual o subieron.")),
    ]
    return [{"enun": t("This supporting question is a conclusion in disguise:", "Esta pregunta de apoyo es una conclusión disfrazada:") + " <strong>" + s + "</strong><br>" + t("Which version is <strong>open</strong>, so the evidence could go either way?", "¿Qué versión es <strong>abierta</strong>, de modo que la evidencia pueda ir en cualquier dirección?"),
             "ops": ops, "ok": 0, "pistas": {1: t("This version still assumes the answer. Look for loaded words.", "Esta versión sigue suponiendo la respuesta. Busque las palabras cargadas."), 2: t("This version still assumes the answer, and adds a guess about blame or motives.", "Esta versión sigue suponiendo la respuesta y añade una suposición sobre culpas o motivos.")}, "exp": e} for s, ops, e in datos]


def casos():
    grupos = [t("Useful supporting question", "Pregunta de apoyo útil"), t("Conclusion in disguise (assumes the answer)", "Conclusión disfrazada (supone la respuesta)"), t("Off topic: it does not help answer the compelling question", "Fuera de tema: no ayuda a responder la convincente")]
    PU = t("Could a source answer it, whichever way the answer goes?", "¿Una fuente podría responderla, salga la respuesta que salga?")
    PD = t("Does it already contain the answer, with a loaded word like “ruin,” “unfair,” or “hurt”?", "¿Ya contiene la respuesta, con una palabra cargada como «arruinar», «injusto» o «perjudicar»?")
    PF = t("Would the answer change anything in the answer to the compelling question?", "¿La respuesta cambiaría algo en la respuesta a la pregunta convincente?")
    def caso(tit, comp, piezas, extra):
        return {"titulo": tit, "intro": t("Compelling question:", "Pregunta convincente:") + f" <strong>{comp}</strong> " + t("Sort each question under it.", "Clasifique cada pregunta que la acompaña."),
                "grupos": grupos, "etiqueta": t("This question is a…", "Esta pregunta es…"), "piezas": [{"t": a, "v": v, "pista": [PU, PD, PF][v]} for a, v in piezas], "extra": extra}
    return [
        caso(t("Case 1 · School closings", "Caso 1 · Cierre de escuelas"), t("When a district closes a school, what should weigh more: the cost or the students’ access?", "Cuando un distrito cierra una escuela, ¿qué debe pesar más: el costo o el acceso de los estudiantes?"),
             [(t("How many students were enrolled in each school in the last five years?", "¿Cuántos estudiantes había matriculados en cada escuela en los últimos cinco años?"), 0),
              (t("How much does the district save each year by closing the two schools?", "¿Cuánto ahorra el distrito cada año al cerrar las dos escuelas?"), 0),
              (t("How far will students travel to their new school?", "¿Cuánto tendrán que viajar los estudiantes hasta su nueva escuela?"), 0),
              (t("Why did the district want to hurt these families?", "¿Por qué quería el distrito perjudicar a estas familias?"), 1),
              (t("What color were the school buildings?", "¿De qué color eran los edificios de las escuelas?"), 2)],
             t(" Three questions bring evidence from both sides: cost (savings) and access (enrollment, distance). The disguised one assumes a bad intention that would have to be shown first.", " Tres preguntas aportan evidencia de los dos lados: el costo (el ahorro) y el acceso (la matrícula, la distancia). La disfrazada supone una mala intención que habría que demostrar primero.")),
        caso(t("Case 2 · The Great Migration", "Caso 2 · La Gran Migración"), t("Was leaving the South enough to improve the life of a working family in 1917?", "¿Bastaba con salir del sur para mejorar la vida de una familia trabajadora en 1917?"),
             [(t("What did workers earn in Mississippi, and what did they earn in Chicago?", "¿Cuánto ganaban los trabajadores en Misisipi y cuánto en Chicago?"), 0),
              (t("How much was rent for a family in each place?", "¿Cuánto costaba el alquiler de una familia en cada lugar?"), 0),
              (t("How many migrants returned to the South, and why?", "¿Cuántos migrantes volvieron al sur, y por qué?"), 0),
              (t("How much better was life in the North?", "¿Cuánto mejor era la vida en el norte?"), 1),
              (t("What was the tallest building in Chicago in 1917?", "¿Cuál era el edificio más alto de Chicago en 1917?"), 2)],
             t(" Notice the question about those who returned: it looks for evidence that could go against the idea that leaving was enough. A good inquiry looks for that kind of evidence on purpose.", " Fíjese en la pregunta sobre quienes volvieron: busca evidencia que podría ir en contra de la idea de que bastaba con salir. Una buena indagación busca ese tipo de evidencia a propósito.")),
        caso(t("Case 3 · The right to vote", "Caso 3 · El derecho al voto"), t("Is it enough to recognize a right in the law for that right to really exist?", "¿Basta con reconocer un derecho en la ley para que exista de verdad?"),
             [(t("What does the Nineteenth Amendment say?", "¿Qué dice la Decimonovena Enmienda?"), 0),
              (t("What share of adult women voted in the elections of the 1920s?", "¿Qué porcentaje de las mujeres adultas votó en las elecciones de los años veinte?"), 0),
              (t("What rules (taxes, tests) kept some citizens from voting after 1920?", "¿Qué reglas (impuestos, pruebas) impidieron votar a algunos ciudadanos después de 1920?"), 0),
              (t("Why was the amendment useless?", "¿Por qué la enmienda no sirvió para nada?"), 1),
              (t("Which suffragist had the most beautiful handwriting?", "¿Qué sufragista tenía la letra más bonita?"), 2)],
             t(" The law, the practice, and the obstacles: three kinds of evidence, three different sources. “Useless” is a conclusion, and probably a wrong one.", " La ley, la práctica y los obstáculos: tres tipos de evidencia, tres fuentes distintas. «No sirvió para nada» es una conclusión, y probablemente equivocada.")),
    ]


def practica():
    A = {"en": ["kinds", "dimensions", "sources", "disguise", "build"], "es": ["tipos", "dimensiones", "fuentes", "disfraz", "construir"]}[C.L]
    mods = [
        (A[0], t("Compelling, supporting, or neither?", "¿Convincente, de apoyo o ninguna?"),
         C.om("m1", t("Use the five-second test. If a quick search answers it and everyone agrees, it is supporting. If informed people could defend different answers with evidence, it is compelling. If only taste decides, it is neither.", "Use la prueba de los cinco segundos. Si una búsqueda rápida la responde y todos están de acuerdo, es de apoyo. Si personas informadas pueden defender respuestas distintas con evidencia, es convincente. Si solo decide el gusto, no es ninguna de las dos."))),
        (A[1], t("Which dimension of the arc?", "¿Qué dimensión del arco?"),
         C.om("m2", t("Ask: is the person deciding what to ask (1), choosing how to look at the problem (2), judging sources (3), or presenting and acting (4)?", "Pregúntese: ¿la persona está decidiendo qué preguntar (1), eligiendo cómo mirar el problema (2), juzgando fuentes (3) o presentando y actuando (4)?"))),
        (A[2], t("Which source answers it?", "¿Qué fuente la responde?"),
         C.om("m3", t("A good supporting question lets you name its source before you look. Choose the source that answers it best.", "Una buena pregunta de apoyo permite nombrar su fuente antes de buscarla. Elija la fuente que la responde mejor."))),
        (A[3], t("A conclusion in disguise", "Una conclusión disfrazada"),
         C.om("m4", t("Each question below already assumes its answer. Choose the open version.", "Cada pregunta ya supone su respuesta. Elija la versión abierta."))),
        (A[4], t("Build an inquiry", "Arme una indagación"),
         C.clasifica("m5", t("Read the compelling question. Then decide, for each question under it, whether it helps answer it, assumes the answer, or is off topic. If something is not right, the questions marked in yellow get a hint.", "Lea la pregunta convincente. Después decida, para cada pregunta que la acompaña, si ayuda a responderla, si supone la respuesta o si está fuera de tema. Si algo no está bien, las preguntas marcadas en amarillo reciben una pista."))),
    ]
    js = (C.js_datos("TIPOS", banco_tipos()) + C.js_datos("DIM", banco_dimension()) + C.js_datos("FUE", banco_fuentes()) +
          C.js_datos("DIS", banco_disfraz()) + C.js_datos("CASOS", casos()) +
          'creaBanco("m1", TIPOS);\ncreaBanco("m2", DIM);\ncreaBanco("m3", FUE);\ncreaBanco("m4", DIS);\ncreaClasifica("m5", CASOS);\n')
    return C.pagina_practica(N, titulo(), t("Five activities · the order of the exercises changes every time · two tries in each one", "Cinco actividades · el orden de los ejercicios cambia cada vez · dos intentos en cada uno"), mods, js)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
